73:   public String getQuery() {
74:     if (query == null) {
75:       String uri = getUri();
76:       int i = uri.indexOf("?");
77:       if (i < 0 || i == uri.length()) {
78:         query = "";
79:       } else {
80:         query = uri.substring(i + 1);
81:       }
82:     }
83: 
84:     return query;
85:   }
