87:   public String getPath() {
88:     if (path == null) {
89:       String uri = getUri();
90:       String noSlash = uri.substring(1);
91:       int i = noSlash.indexOf("?");
92:       if (i < 0) {
93:         path = noSlash;
94:       } else {
95:         path = noSlash.substring(0, i);
96:       }
97:     }
98: 
