31: public class RoutingAdapter implements Handler<Routed<HttpExchange>> {
32: 
33:   private final PathBinding pathBinding;
34:   private final ResponseFactory responseFactory;
35:   private final Endpoint endpoint;
36:   private final List<String> methods;
37: 
38:   public RoutingAdapter(PathBinding pathBinding, ResponseFactory responseFactory, Endpoint endpoint, String... methods) {
39:     this.pathBinding = pathBinding;
40:     this.responseFactory = responseFactory;
41:     this.endpoint = endpoint;
42:     this.methods = Arrays.asList(methods);
43:   }
44: 
45:   @Override
46:   public void handle(Routed<HttpExchange> routedHttpExchange) {
47:     HttpExchange exchange = routedHttpExchange.get();
48:     HttpRequest request = exchange.getRequest();
49:     if (methods.isEmpty() || methods.contains(request.getMethod().getName())) {
50:       String path = exchange.getPath();
51: 
52:       Map<String, String> params = pathBinding.map(path);
53:       if (params != null) {
54:         Response response = responseFactory.create(routedHttpExchange, params);
55:         endpoint.respond(response.getRequest(), response);
56:         return;
57:       }
58:     }
59: 
60:     routedHttpExchange.next();
61:   }
