113:     int expiryMins = sessionConfig.getCookieExpiryMins();
114:     if (expiryMins > 0) {
115:       Calendar expires = Calendar.getInstance(TimeZone.getTimeZone("UTC"));
116:       expires.add(Calendar.MINUTE, expiryMins);
117:       setCookie(id, expires.getTime());
118:     } else {
119:       setCookie(id, null);
120:     }
121: 
122:     sessionConfig.getSessionListener().sessionInitiated(id);
123:     return id;
