794:   /**
795:    * Applies the custom operation function to this promise.
796:    * <p>
797:    * This method can be used to apply custom operations without breaking the “code flow”.
798:    * It works particularly well with method references.
799:    * <pre class="java">{@code
800:    * import ratpack.exec.Promise;
801:    * import ratpack.test.exec.ExecHarness;
802:    *
803:    * import static org.junit.Assert.assertEquals;
804:    *
805:    * public class Example {
806:    *   public static void main(String... args) throws Exception {
807:    *     Integer value = ExecHarness.yieldSingle(e ->
808:    *         Promise.value(1)
809:    *           .apply(Example::dubble)
810:    *           .apply(Example::triple)
811:    *     ).getValue();
812:    *
813:    *     assertEquals(Integer.valueOf(6), value);
814:    *   }
815:    *
816:    *   public static Promise<Integer> dubble(Promise<Integer> input) {
817:    *     return input.map(i -> i * 2);
818:    *   }
819:    *
820:    *   public static Promise<Integer> triple(Promise<Integer> input) {
821:    *     return input.map(i -> i * 3);
822:    *   }
823:    * }
824:    * }</pre>
825:    * <p>
826:    * If the apply function throws an exception, the returned promise will fail.
827:    * <pre class="java">{@code
828:    * import ratpack.exec.Promise;
829:    * import ratpack.test.exec.ExecHarness;
830:    *
831:    * import static org.junit.Assert.assertEquals;
832:    *
833:    * public class Example {
834:    *   public static void main(String... args) throws Exception {
835:    *     Throwable error = ExecHarness.yieldSingle(e ->
836:    *         Promise.value(1)
837:    *           .apply(Example::explode)
838:    *     ).getThrowable();
839:    *
840:    *     assertEquals("bang!", error.getMessage());
841:    *   }
842:    *
843:    *   public static Promise<Integer> explode(Promise<Integer> input) throws Exception {
844:    *     throw new Exception("bang!");
845:    *   }
846:    * }
847:    * }</pre>
848:    * <p>
849:    * If the promise having the operation applied to fails, the operation will not be applied.
850:    * <pre class="java">{@code
851:    * import ratpack.exec.Promise;
852:    * import ratpack.test.exec.ExecHarness;
853:    *
854:    * import static org.junit.Assert.assertEquals;
855:    *
856:    * public class Example {
857:    *   public static void main(String... args) throws Exception {
858:    *     Throwable error = ExecHarness.yieldSingle(e ->
859:    *         Promise.<Integer>error(new Exception("bang!"))
860:    *           .apply(Example::dubble)
861:    *     ).getThrowable();
862:    *
863:    *     assertEquals("bang!", error.getMessage());
864:    *   }
865:    *
866:    *   public static Promise<Integer> dubble(Promise<Integer> input) {
867:    *     return input.map(i -> i * 2);
868:    *   }
869:    * }
870:    * }</pre>
871:    *
872:    * @param <O> the type of promised object after the operation
873:    * @param function the operation implementation
874:    * @return the transformed promise
875:    */
876:   default <O> Promise<O> apply(Function<? super Promise<T>, ? extends Promise<O>> function) {
877:     try {
878:       return function.apply(this);
879:     } catch (Throwable e) {
880:       return Promise.error(e);
881:     }
882:   }
