803:    * import static org.junit.Assert.assertEquals;
804:    *
805:    * public class Example {
806:    *   public static void main(String... args) throws Exception {
807:    *     Integer value = ExecHarness.yieldSingle(e ->
808:    *         Promise.value(1)
809:    *           .apply(Example::dubble)
810:    *           .apply(Example::triple)
811:    *     ).getValue();
812:    *
813:    *     assertEquals(Integer.valueOf(6), value);
814:    *   }
815:    *
816:    *   public static Promise<Integer> dubble(Promise<Integer> input) {
817:    *     return input.map(i -> i * 2);
