1272:    *     int numJobs = 1000;
1273:    *     int maxAtOnce = 10;
1274:    *
1275:    *     ExecResult<Integer> result = ExecHarness.yieldSingle(exec -> {
1276:    *       AtomicInteger maxConcurrent = new AtomicInteger();
1277:    *       AtomicInteger active = new AtomicInteger();
1278:    *       AtomicInteger done = new AtomicInteger();
1279:    *
1280:    *       Throttle throttle = Throttle.ofSize(maxAtOnce);
