50: class ContentStreamingRequestAction extends RequestActionSupport<StreamedResponse> {
51:   private final AtomicBoolean subscribedTo = new AtomicBoolean();
52: 
53:   public ContentStreamingRequestAction(Action<? super RequestSpec> requestConfigurer, URI uri, Execution execution, ByteBufAllocator byteBufAllocator, int redirectCount) {
54:     super(requestConfigurer, uri, execution, byteBufAllocator, redirectCount);
55:   }
56: 
57:   @Override
58:   protected RequestActionSupport<StreamedResponse> buildRedirectRequestAction(Action<? super RequestSpec> redirectRequestConfig, URI locationUrl, int redirectCount) {
59:     return new ContentStreamingRequestAction(redirectRequestConfig, locationUrl, execution, byteBufAllocator, redirectCount);
60:   }
61: 
62:   @Override
63:   protected void addResponseHandlers(ChannelPipeline p, Downstream<? super StreamedResponse> downstream) {
64:     p.addLast("httpResponseHandler", new SimpleChannelInboundHandler<HttpResponse>(false) {
65:       @Override
66:       public void channelRead0(ChannelHandlerContext ctx, HttpResponse msg) throws Exception {
67:         // Switch auto reading off so we can control the flow of response content
68:         p.channel().config().setAutoRead(false);
69:         execution.onCleanup(() -> {
70:           if (!subscribedTo.get() && ctx.channel().isOpen()) {
71:             ctx.close();
72:           }
73:         });
74: 
75:         final Headers headers = new NettyHeadersBackedHeaders(msg.headers());
76:         final Status status = new DefaultStatus(msg.status());
77: 
78:         success(downstream, new DefaultStreamedResponse(p, status, headers));
79:       }
80: 
81:       @Override
82:       public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) throws Exception {
83:         ctx.close();
84:         error(downstream, cause);
85:       }
86:     });
87:   }
