89:   private class DefaultStreamedResponse implements StreamedResponse {
90:     private final ChannelPipeline channelPipeline;
91:     private final Status status;
92:     private final Headers headers;
93: 
94:     public DefaultStreamedResponse(ChannelPipeline p, Status status, Headers headers) {
95:       this.channelPipeline = p;
96:       this.status = status;
97:       this.headers = headers;
98:     }
99: 
100:     @Override
101:     public Status getStatus() {
102:       return status;
103:     }
104: 
105:     @Override
106:     public int getStatusCode() {
107:       return status.getCode();
108:     }
109: 
110:     @Override
111:     public Headers getHeaders() {
112:       return headers;
113:     }
114: 
115:     @Override
116:     public TransformablePublisher<ByteBuf> getBody() {
117:       return Streams.transformable(new HttpContentPublisher(channelPipeline));
118:     }
119: 
120:     @Override
121:     public void send(Response response) {
122:       send(response, Action.noop());
123:     }
124: 
125:     @Override
126:     public void send(Response response, Action<? super MutableHeaders> headerMutator) {
127:       response.getHeaders().copy(this.headers);
128:       response.getHeaders().remove(HttpHeaderConstants.CONTENT_LENGTH); // responses will always be chunked
129:       try {
130:         headerMutator.execute(response.getHeaders());
131:       } catch (Exception e) {
132:         throw uncheck(e);
133:       }
134:       response.getHeaders().set(HttpHeaderConstants.TRANSFER_ENCODING, HttpHeaderConstants.CHUNKED);
135: 
136:       response.status(this.status);
137:       response.sendStream(getBody());
138:     }
139:   }
