26: public class DefaultByAcceptsResponder implements ByAcceptsResponder {
27: 
28:   private final Map<String, Runnable> map = new LinkedHashMap<String, Runnable>(3);
29:   private String first;
30:   private final Context context;
31: 
32:   public DefaultByAcceptsResponder(Context context) {
33:     this.context = context;
34:   }
35: 
36:   public ByAcceptsResponder type(String mimeType, Runnable runnable) {
37:     if (mimeType == null) {
38:       throw new IllegalArgumentException("mimeType cannot be null");
39:     }
40: 
41:     String trimmed = mimeType.trim();
42:     if (trimmed.isEmpty()) {
43:       throw new IllegalArgumentException("mimeType cannot be a blank string");
44:     }
45: 
46:     if (first == null) {
47:       first = trimmed;
48:     }
49:     map.put(trimmed, runnable);
50:     return this;
51:   }
52: 
53:   public ByAcceptsResponder plainText(Runnable runnable) {
54:     return type("text/plain", runnable);
55:   }
56: 
57:   public ByAcceptsResponder html(Runnable runnable) {
58:     return type("text/html", runnable);
59:   }
60: 
61:   public ByAcceptsResponder json(Runnable runnable) {
62:     return type("application/json", runnable);
63:   }
64: 
65:   public ByAcceptsResponder xml(Runnable runnable) {
66:     return type("application/xml", runnable);
67:   }
68: 
69:   public void build() {
70:     if (first == null) {
71:       context.clientError(406);
72:       return;
73:     }
74: 
75:     List<String> types = new ArrayList<String>(map.keySet());
76:     Collections.reverse(types);
77:     String winner = first;
78: 
79:     String acceptHeader = context.getRequest().getHeader(HttpHeaders.Names.ACCEPT);
80:     if (acceptHeader != null && !acceptHeader.isEmpty()) {
81:       winner = MimeParse.bestMatch(types, acceptHeader);
82:     }
83: 
84:     if (winner == null || winner.isEmpty()) {
85:       context.clientError(406);
86:     } else {
87:       context.getResponse().setHeader(HttpHeaders.Names.CONTENT_TYPE, winner);
88:       Runnable runnable = map.get(winner);
89:       runnable.run();
90:     }
91:   }
92: 
93: }
