29: /**
30:  * Note, this publisher does not respect back pressure.
31:  * Must be used in conjunction with a throttling strategy.
32:  */
33: public class PeriodicPublisher<T> implements Publisher<T> {
34:   private final ScheduledExecutorService executorService;
35:   private final Function<Integer, T> producer;
36:   private final long delay;
37:   private final TimeUnit timeUnit;
38: 
39:   public PeriodicPublisher(ScheduledExecutorService executorService, Function<Integer, T> producer, long delay, TimeUnit timeUnit) {
40:     this.executorService = executorService;
41:     this.producer = producer;
42:     this.delay = delay;
43:     this.timeUnit = timeUnit;
44:   }
45: 
46:   @Override
47:   public void subscribe(final Subscriber<? super T> s) {
48:     s.onSubscribe(new Subscription() {
49:       private final AtomicInteger counter = new AtomicInteger(0);
50:       private final ScheduledFuture<?> future = executorService.scheduleWithFixedDelay(() -> {
51:         int i = counter.getAndIncrement();
