70: 
71:     try {
72:       contextFactoryThreadLocal.set(execContextSupplier);
73:       new InterceptedOperation(execType, interceptors) {
74:         @Override
75:         protected void performOperation() throws Exception {
76:           action.execute(getContext());
77:         }
