25: public class DefaultByContentSpec implements ByContentSpec {
26: 
27:   public static final String TYPE_PLAIN_TEXT = "text/plain";
28:   public static final String TYPE_HTML = "text/html";
29:   public static final String TYPE_JSON = "application/json";
30:   public static final String TYPE_XML = "application/xml";
31: 
32:   private final Map<String, Handler> map;
33:   private Handler noMatchHandler = ctx -> ctx.clientError(406);
34: 
35:   public DefaultByContentSpec(Map<String, Handler> map) {
36:     this.map = map;
37:   }
38: 
39:   @Override
40:   public ByContentSpec type(String mimeType, Block handler) {
41:     return type(mimeType, ctx -> handler.execute());
42:   }
43: 
44:   @Override
45:   public ByContentSpec type(String mimeType, Handler handler) {
46:     if (mimeType == null) {
47:       throw new IllegalArgumentException("mimeType cannot be null");
48:     }
49: 
50:     String trimmed = mimeType.trim();
51:     if (trimmed.isEmpty()) {
52:       throw new IllegalArgumentException("mimeType cannot be a blank string");
53:     }
54: 
55:     if (trimmed.contains("*")) {
56:       throw new IllegalArgumentException("mimeType cannot include wildcards");
57:     }
58: 
59:     map.put(trimmed, handler);
60:     return this;
61:   }
62: 
63:   @Override
64:   public ByContentSpec plainText(Block handler) {
65:     return type(TYPE_PLAIN_TEXT, handler);
66:   }
67: 
68:   @Override
69:   public ByContentSpec plainText(Handler handler) {
70:     return type(TYPE_PLAIN_TEXT, handler);
71:   }
72: 
