79:   public ByContentSpec html(Handler handler) {
80:     return type(TYPE_HTML, handler);
81:   }
82: 
83:   @Override
84:   public ByContentSpec json(Block handler) {
85:     return type(TYPE_JSON, handler);
86:   }
87: 
88:   @Override
89:   public ByContentSpec json(Handler handler) {
90:     return type(TYPE_JSON, handler);
91:   }
92: 
93:   @Override
94:   public ByContentSpec xml(Block handler) {
95:     return type(TYPE_XML, handler);
96:   }
97: 
98:   @Override
99:   public ByContentSpec xml(Handler handler) {
100:     return type(TYPE_XML, handler);
101:   }
102: 
103:   @Override
104:   public ByContentSpec noMatch(Block handler) {
105:     noMatchHandler = ctx -> handler.execute();
106:     return this;
107:   }
108: 
109:   @Override
110:   public ByContentSpec noMatch(String mimeType) {
111:     return noMatch(ctx -> {
112:       ctx.getResponse().contentType(mimeType);
113:       ctx.insert(map.get(mimeType));
114:     });
115:   }
