31: /**
32:  * Static factory methods for creating {@link LaunchConfig} objects using various strategies.
33:  * <p>
34:  * Designed to be used to construct a launch config via a {@link Properties} instance.
35:  * <p>
36:  * Most methods eventually delegate to {@link #createWithBaseDir(ClassLoader, java.io.File, java.util.Properties)}.
37:  * <p>
38:  * When things go wrong, a {@link LaunchException} will be thrown.
39:  */
40: public abstract class LaunchConfigFactory {
41: 
42:   /**
43:    * Value: {@value}.
44:    *
45:    * @see #createFromGlobalProperties(ClassLoader, java.util.Properties, java.util.Properties)
46:    */
47:   public static final String SYSPROP_PREFIX_PROPERTY = "ratpack.syspropPrefix";
48: 
49:   /**
50:    * Value: {@value}.
51:    *
52:    * @see #createFromGlobalProperties(ClassLoader, java.util.Properties, java.util.Properties)
53:    */
54:   public static final String SYSPROP_PREFIX_DEFAULT = "ratpack.";
55: 
56:   public static final String CONFIG_RESOURCE_PROPERTY = "configResource";
57:   public static final String CONFIG_RESOURCE_DEFAULT = "ratpack.properties";
58: 
59:   private LaunchConfigFactory() {
60:   }
61: 
62:   /**
63:    * Delegates to {@link #createFromGlobalProperties(ClassLoader, String, java.util.Properties, java.util.Properties)}, extracting the “propertyPrefix” from the “globalProperties”.
64:    * <p>
65:    * Determines the “propertyPrefix” value and delegates to {@link #createFromGlobalProperties(ClassLoader, String, java.util.Properties, java.util.Properties)}.
66:    * The value is determined by: {@code globalProperties.getProperty(SYSPROP_PREFIX_PROPERTY, SYSPROP_PREFIX_DEFAULT)}
67:    *
68:    * @param classLoader The classloader to use to find the properties file.
69:    * @param globalProperties The environmental (override) properties
70:    * @param defaultProperties The default properties to use when a property is omitted
71:    * @return A launch config
72:    */
73:   public static LaunchConfig createFromGlobalProperties(ClassLoader classLoader, Properties globalProperties, Properties defaultProperties) {
74:     String propertyPrefix = globalProperties.getProperty(SYSPROP_PREFIX_PROPERTY, SYSPROP_PREFIX_DEFAULT);
75:     return createFromGlobalProperties(classLoader, propertyPrefix, globalProperties, defaultProperties);
76:   }
77: 
78:   /**
79:    * Delegates to {@link #createFromProperties(ClassLoader, java.util.Properties, java.util.Properties)} after extracting the “prefixed” properties from the global properties.
80:    * <p>
81:    * The properties of {@code globalProperties} that begin with {@code propertyPrefix} are extracted into a new property set,
82:    * with the property names having the prefix removed.
83:    * This becomes the {@code overrideProperties} for the delegation to {@link #createFromProperties(ClassLoader, java.util.Properties, java.util.Properties)}.
84:    *
85:    * @param classLoader The classloader to use to find the properties file
86:    * @param propertyPrefix The prefix of properties in {@code globalProperties} that should be extracted to form the override properties
87:    * @param globalProperties The environmental (override) properties
88:    * @param defaultProperties The default properties to use when a property is omitted
89:    * @return A launch config
90:    */
91:   public static LaunchConfig createFromGlobalProperties(ClassLoader classLoader, String propertyPrefix, Properties globalProperties, Properties defaultProperties) {
92:     Properties deprefixed = new Properties();
93:     extractProperties(propertyPrefix, globalProperties, deprefixed);
94:     return createFromProperties(classLoader, deprefixed, defaultProperties);
95:   }
96: 
97:   /**
98:    * Extracts the properties prefixed with {@value #SYSPROP_PREFIX_DEFAULT} from the system properties, without the prefix.
99:    *
100:    * @return the properties prefixed with {@value #SYSPROP_PREFIX_DEFAULT} from the system properties, without the prefix.
101:    */
102:   public static Properties getDefaultPrefixedProperties() {
103:     Properties deprefixed = new Properties();
104:     extractProperties(SYSPROP_PREFIX_DEFAULT, System.getProperties(), deprefixed);
105:     return deprefixed;
106:   }
107: 
108:   private static void extractProperties(String propertyPrefix, Properties properties, Map<? super String, ? super String> destination) {
109:     for (String propertyName : properties.stringPropertyNames()) {
110:       if (propertyName.startsWith(propertyPrefix)) {
111:         destination.put(propertyName.substring(propertyPrefix.length()), properties.getProperty(propertyName));
112:       }
113:     }
114:   }
115: 
116:   /**
117:    * Delegates to {@link #createFromFile(ClassLoader, java.io.File, java.io.File, java.util.Properties, java.util.Properties)}, after trying to find the config properties file.
118:    * <p>
119:    * The {@code overrideProperties} are queried for the {@link #CONFIG_RESOURCE_PROPERTY} (defaulting to {@link #CONFIG_RESOURCE_DEFAULT}).
120:    * The {@code classLoader} is asked for the classpath resource with this name.
121:    * <p>
122:    * If the resource DOES NOT exist, {@link #createFromFile(ClassLoader, java.io.File, java.io.File, java.util.Properties, java.util.Properties)} is called with
123:    * the current JVM user dir as the {@code baseDir} and {@code null} as the {@code configFile}.
124:    * <p>
125:    * If the resource DOES exist, {@link #createFromFile(ClassLoader, java.io.File, java.io.File, java.util.Properties, java.util.Properties)} is called with
126:    * that file resource as the {@code configFile}, and its parent directory as the {@code baseDir}.
127:    *
