163:    * @param overrideProperties The properties that override default and file properties
164:    * @param defaultProperties The default properties to use when a property is omitted
165:    * @return a launch config
166:    */
167:   public static LaunchConfig createFromFile(ClassLoader classLoader, File baseDir, @Nullable File configFile, Properties overrideProperties, Properties defaultProperties) {
168:     Properties fileProperties = new Properties(defaultProperties);
169:     if (configFile != null && configFile.exists()) {
