32: @Singleton
33: public class BlockingExecTimingInterceptor implements ExecInterceptor {
34: 
35:   private final MetricRegistry metricRegistry;
36:   private final CodaHaleMetricsModule.Config config;
37: 
38:   @Inject
39:   public BlockingExecTimingInterceptor(MetricRegistry metricRegistry, CodaHaleMetricsModule.Config config) {
40:     this.metricRegistry = metricRegistry;
41:     this.config = config;
42:   }
43: 
44:   @Override
45:   public void intercept(Execution execution, ExecType type, Block continuation) throws Exception {
46:     if (type == ExecType.BLOCKING) {
47:       Optional<Request> requestOpt = execution.maybeGet(Request.class);
48:       if (requestOpt.isPresent()) {
49:         Request request = requestOpt.get();
50:         String tag = buildBlockingTimerTag(request.getPath(), request.getMethod().getName());
51:         Timer.Context timer = metricRegistry.timer(tag).time();
52:         try {
53:           continuation.execute();
54:         } finally {
55:           timer.stop();
56:         }
57:         return;
58:       }
59:     }
60: 
61:     continuation.execute();
62:   }
63: 
64:   private String buildBlockingTimerTag(String requestPath, String requestMethod) {
65:     String tagName = requestPath.equals("") ? "root" : requestPath.replace("/", ".");
66: 
67:     if (config.getRequestMetricGroups() != null) {
68:       for (Map.Entry<String, String> metricGrouping : config.getRequestMetricGroups().entrySet()) {
69:         if (requestPath.matches(metricGrouping.getValue())) {
70:           tagName = metricGrouping.getKey();
71:           break;
72:         }
73:       }
74:     }
75: 
76:     return tagName + "." + requestMethod.toLowerCase() + "-blocking";
77:   }
78: 
