48:  * public class Example {
49:  *
50:  *   static class ExampleHealthCheck implements HealthCheck {
51:  *     public String getName() {
52:  *       return "example"; // must be unique within the application
53:  *     }
54:  *
55:  *     public Promise<HealthCheck.Result> check(ExecControl execControl) throws Exception {
56:  *       return execControl.promiseOf(HealthCheck.Result.healthy());
57:  *     }
58:  *   }
59:  *
60:  *   public static void main(String... args) throws Exception {
61:  *     EmbeddedApp.of(s -> s
62:  *       .registryOf(r -> r
63:  *         .add(new ExampleHealthCheck())
64:  *         .add(HealthCheck.of("inline", execControl -> // alternative way to implement health checks
65:  *           execControl.promiseOf(HealthCheck.Result.unhealthy("FAILED"))
66:  *         ))
67:  *       )
68:  *       .handlers(c -> c
69:  *         .get("health/:name?", new HealthCheckHandler())
70:  *       )
71:  *     ).test(httpClient -> {
72:  *       // Run all health checks
73:  *       String result = httpClient.getText("health");
74:  *       String[] results = result.split("\n");
75:  *       assertEquals(2, results.length);
76:  *       assertEquals("example : HEALTHY", results[0]);
77:  *       assertEquals("inline : UNHEALTHY [FAILED]", results[1]);
78:  *
79:  *       // Run a single health check
80:  *       result = httpClient.getText("health/example");
81:  *       assertEquals("example : HEALTHY", result);
82:  *     });
83:  *   }
84:  * }
85:  * }</pre>
86:  *
87:  * <h3>The output format</h3>
88:  * <p>
89:  * The handler creates a {@link HealthCheckResults} object with the results of running the health checks and {@link Context#render(Object) renders} it.
90:  * Ratpack provides a default renderer for {@link HealthCheckResults} objects, that renders results as plain text one per line with the format:
91:  * <pre>{@code name : HEALTHY|UNHEALTHY [message] [exception]}</pre>
92:  * <p>
93:  * To change the output format, simply add your own renderer for this type to the registry.
94:  * <p>
95:  * When reporting a single health check, the {@link HealthCheck.Result} object is rendered directly.
96:  * Ratpack also provides a default renderer for this type.
97:  *
98:  * <h3>Concurrency</h3>
99:  * <p>
100:  * By default, health checks are executed concurrently.
101:  * An individual {@link ratpack.exec.Execution} is created for each health check to be executed and all are initiated simultaneously.
102:  * A {@code concurrency} parameter can be specified when {@link #HealthCheckHandler(String, int) constructing} this handler to alter this behaviour.
103:  *
104:  * <h3>Rendering single health checks</h3>
105:  * <p>
106:  * The handler checks for the presence of a {@link Context#getPathTokens() path token} to indicate the name of an individual check to execute.
107:  * By default, the token is named {@value #DEFAULT_NAME_TOKEN}.
108:  * If a path token is present, but indicates the name of a non-existent health check, a {@code 404} {@link Context#clientError(int) client error} will be raised.
109:  *
110:  * @see ratpack.health.HealthCheck
111:  * @see ratpack.health.HealthCheckResults
112:  */
113: public class HealthCheckHandler implements Handler {
114: 
115:   /**
116:    * The default concurrency level for executing health checks, 0, meaning unlimited concurrency.
117:    *
118:    * @see #HealthCheckHandler(String, int)
119:    */
120:   public static final int DEFAULT_CONCURRENCY_LEVEL = 0;
121: 
122:   /**
123:    * The default path token name that indicates the individual health check to run.
124:    *
125:    * Value: {@value}
126:    *
127:    * @see #HealthCheckHandler(String, int)
128:    */
129:   public static final String DEFAULT_NAME_TOKEN = "name";
130:   private static final TypeToken<HealthCheck> HEALTH_CHECK_TYPE_TOKEN = TypeToken.of(HealthCheck.class);
131: 
132:   private final String name;
133:   private final int concurrencyLevel;
134: 
135:   /**
136:    * Uses the default values of {@link #DEFAULT_NAME_TOKEN} and {@link #DEFAULT_CONCURRENCY_LEVEL}.
137:    *
138:    * @see #HealthCheckHandler(String, int)
139:    */
140:   public HealthCheckHandler() {
141:     this(DEFAULT_NAME_TOKEN, DEFAULT_CONCURRENCY_LEVEL);
142:   }
143: 
144:   /**
145:    * Uses the {@link #DEFAULT_CONCURRENCY_LEVEL} and the given name for the health check identifying path token.
146:    *
147:    * @param pathTokenName health check name
148:    * @see #HealthCheckHandler(String, int)
149:    */
150:   public HealthCheckHandler(String pathTokenName) {
151:     this(pathTokenName, DEFAULT_CONCURRENCY_LEVEL);
152:   }
153: 
154:   /**
155:    * Uses the {@link #DEFAULT_NAME_TOKEN} and the given concurrency level.
156:    *
157:    * @param concurrencyLevel the concurrency level
158:    * @see #HealthCheckHandler(String, int)
159:    */
160:   public HealthCheckHandler(int concurrencyLevel) {
161:     this(null, concurrencyLevel);
162:   }
163: 
164:   /**
165:    * Constructor.
166:    * <p>
167:    * The path token name parameter specifies the name of the path token that, if present, indicates the single health check to execute.
168:    * If this path token is not present, all checks will be run.
169:    * <p>
170:    * The concurrency level indicates  the maximum allowed concurrency of health check execution.
171:    * <ul>
172:    * <li><code>&lt; 1</code> - infinite concurrency</li>
173:    * <li><code>= 1</code> - serialised (i.e. maximum concurrency of 1)</li>
174:    * <li><code>&gt; 1</code> - bounded concurrency</li>
175:    * </ul>
176:    * <p>
177:    * The actual parallelism of the health check executions is ultimately determined by the size of the application event loop.
178:    * General, the default value of {@code 0} (i.e. unbounded) is appropriate unless there are many health checks that are executed frequently as this may degrade the performance of other requests.
179:    *
180:    * @param pathTokenName the name of health check
181:    * @param concurrencyLevel the level of concurrency to use when executing health checks
182:    */
183:   protected HealthCheckHandler(String pathTokenName, int concurrencyLevel) {
184:     this.name = pathTokenName;
185:     this.concurrencyLevel = concurrencyLevel;
186:   }
187: 
188:   /**
189:    * The level of concurrency to use when executing health checks.
190:    *
191:    * @return the level of concurrency to use when executing health checks
192:    * @see #HealthCheckHandler(String, int)
193:    */
194:   public int getConcurrencyLevel() {
195:     return concurrencyLevel;
196:   }
197: 
198:   /**
199:    * The name of the path token that may indicate a particular health check to execute.
200:    *
201:    * @return the name of the path token that may indicate a particular health check to execute
202:    */
203:   public String getName() {
204:     return name;
205:   }
206: 
207:   /**
208:    * Renders health checks.
209:    *
210:    * @param context the request context
211:    */
212:   @Override
213:   public void handle(Context context) {
214:     context.getResponse().getHeaders()
215:       .add("Cache-Control", "no-cache, no-store, must-revalidate")
216:       .add("Pragma", "no-cache")
217:       .add("Expires", 0);
218: 
219:     try {
220:       if (name != null) {
221:         String checkName = context.getPathTokens().get(name);
222:         if (checkName != null) {
223:           handleByName(context, checkName);
224:           return;
225:         }
226:       }
227: 
228:       handleAll(context);
229:     } catch (Exception e) {
230:       context.error(e);
231:     }
232:   }
233: 
234:   private void handleByName(Context context, String name) throws Exception {
235:     Optional<HealthCheck> healthCheck = context.first(HEALTH_CHECK_TYPE_TOKEN, it -> it.getName().equals(name) ? it : null);
236: 
237:     if (!healthCheck.isPresent()) {
238:       context.clientError(404);
239:       return;
240:     }
241:     try {
242:       Promise<HealthCheck.Result> promise = healthCheck.get().check(context.getExecution().getControl());
243:       promise.onError(throwable -> {
244:         context.render(new HealthCheckResults(ImmutableSortedMap.of(healthCheck.get().getName(), HealthCheck.Result.unhealthy(throwable))));
245:       }).then(r -> {
246:         context.render(new HealthCheckResults(ImmutableSortedMap.of(healthCheck.get().getName(), r)));
247:       });
248:     } catch (Exception ex) {
249:       context.render(new HealthCheckResults(ImmutableSortedMap.of(healthCheck.get().getName(), HealthCheck.Result.unhealthy(ex))));
250:     }
251:   }
252: 
253:   private void handleAll(Context context) throws Exception {
254:     SortedMap<String, HealthCheck.Result> hcheckResults = new ConcurrentSkipListMap<>();
255: 
256:     SortedMap<String, Promise<HealthCheck.Result>> promises = new ConcurrentSkipListMap<>();
257:     context.getAll(HealthCheck.class).forEach(hcheck -> {
258:       try {
259:         Promise<HealthCheck.Result> promise = hcheck.check(context.getExecution().getControl());
260:         promises.put(hcheck.getName(), promise);
261:       } catch (Exception ex) {
262:         hcheckResults.put(hcheck.getName(), HealthCheck.Result.unhealthy(ex));
263:       }
264:     });
265: 
266:     if (promises.size() == 0) {
267:       context.render(new HealthCheckResults(ImmutableSortedMap.copyOfSorted(hcheckResults)));
268:       return;
269:     }
270: 
271:     context.promise(f -> {
272:       // execute promises in parallel based on the concurrencyLevel
273:       // count finished health checks. If all are done, render results
274:       AtomicInteger executedPromisesCountDown = new AtomicInteger(promises.size());
275:       // count health checks waiting for execution.
276:       AtomicInteger toExecPromisesCountDown = new AtomicInteger(promises.size());
277:       // collect health checks to execute in the next run. Used when concurrencyLevel > 1
278:       Map<String, Promise<HealthCheck.Result>> toExecPromises = new ConcurrentHashMap<>();
279: 
280:       promises.forEach((name, p) -> {
281:         boolean execParallel = false;
282:         if (concurrencyLevel <= 0) {
283:           // execute all health checks in parallel
284:           execParallel = true;
285:         } else if (concurrencyLevel == 1) {
286:           // execute promise by promise, in sequence
287:           execParallel = false;
288:         } else {
289:           // collect promises into group of concurrencyLevel size or into group of last promises to execute
290:           toExecPromises.put(name, p);
291:           if (toExecPromisesCountDown.decrementAndGet() > 0 && toExecPromises.size() < concurrencyLevel) {
292:             return;
293:           }
294:           // execute promises in group in parallel
295:           execParallel = true;
296:         }
297: 
298:         if (toExecPromises.size() > 0) {
299:           // promise of immutable map of promises to execute, controls construction and their parallel execution while allows
300:           // safe freeing of toExecPromises map.
301:           context.promiseOf(ImmutableMap.copyOf(toExecPromises)).then(map -> {
302:             // control finalization of parent promise
303:             AtomicInteger groupOfPromisesCountDown = new AtomicInteger(map.size());
304:             context.promise(f2 -> {
305:               map.forEach((name2, p2) -> {
306:                 // execute promise p2 and check end condition: either last promise in group or last promise globally
307:                 execPromiseWithEndCondition(context, name2, p2, f2, hcheckResults, groupOfPromisesCountDown, executedPromisesCountDown);
308:               });
309:             }).then(finish -> {
310:               if (finish == Boolean.TRUE) {
311:                 f.success(hcheckResults);
312:               }
313:             });
314:           });
315: 
316:           toExecPromises.clear();
317: 
318:         } else {
319:           if (execParallel) {
320:             // execute promise and if last promise globally, return health check results
321:             execPromiseWithEndResult(context, name, p, f, hcheckResults, executedPromisesCountDown);
322:           } else {
323:             context.promise(f2 -> {
324:               // execute promise p and check end condition: if last promise globally
325:               execPromiseWithEndCondition(context, name, p, f2, hcheckResults, null, executedPromisesCountDown);
326:             }).then(finish -> {
327:               if (finish == Boolean.TRUE) {
328:                 f.success(hcheckResults);
329:               }
330:             });
331:           }
332:         }
333:       });
334:     }).then(results -> {
335:       context.render(new HealthCheckResults(ImmutableSortedMap.copyOfSorted(hcheckResults)));
336:     });
337:   }
338: 
339:   private void execPromiseWithEndResult(
340:     Context context,
341:     String name,
342:     Promise<HealthCheck.Result> promise,
343:     Fulfiller<Object> fulfiller,
344:     SortedMap<String, HealthCheck.Result> hcheckResults,
345:     AtomicInteger executedPromisesCountDown) {
346: 
347:     context.exec().onComplete(execution -> {
348:       if (executedPromisesCountDown.decrementAndGet() == 0) {
349:         fulfiller.success(hcheckResults);
350:       }
351:     }).onError(throwable -> {
352:       hcheckResults.put(name, HealthCheck.Result.unhealthy(throwable));
353:       if (executedPromisesCountDown.decrementAndGet() == 0) {
354:         fulfiller.success(hcheckResults);
355:       }
356:     }).start(execution -> {
357:       promise.then(r -> {
358:         hcheckResults.put(name, r);
359:       });
360:     });
361:   }
362: 
363:   private void execPromiseWithEndCondition(
364:     Context context,
365:     String name,
366:     Promise<HealthCheck.Result> promise,
367:     Fulfiller<Object> fulfiller,
368:     SortedMap<String, HealthCheck.Result> hcheckResults,
369:     AtomicInteger groupOfPromisesCountDown, AtomicInteger executedPromisesCountDown) {
370: 
371:     context.exec().onComplete(execution -> {
372:       int i = executedPromisesCountDown != null ? executedPromisesCountDown.decrementAndGet() : 0;
373:       if (groupOfPromisesCountDown != null) {
374:         if (groupOfPromisesCountDown.decrementAndGet() == 0 || i == 0) {
375:           fulfiller.success(i == 0 ? Boolean.TRUE : Boolean.FALSE);
376:         }
377:       } else {
378:         fulfiller.success(i == 0 ? Boolean.TRUE : Boolean.FALSE);
379:       }
380:     }).onError(throwable -> {
381:       hcheckResults.put(name, HealthCheck.Result.unhealthy(throwable));
382:       int i = executedPromisesCountDown != null ? executedPromisesCountDown.decrementAndGet() : 0;
383:       if (groupOfPromisesCountDown != null) {
384:         if (groupOfPromisesCountDown.decrementAndGet() == 0 || i == 0) {
385:           fulfiller.success(i == 0 ? Boolean.TRUE : Boolean.FALSE);
386:         }
387:       } else {
388:         fulfiller.success(i == 0 ? Boolean.TRUE : Boolean.FALSE);
389:       }
390:     }).start(execution -> {
391:       promise.then(r -> {
392:         hcheckResults.put(name, r);
393:       });
394:     });
395:   }
396: }
