115:   /**
116:    * The default concurrency level for executing health checks, 0, meaning unlimited concurrency.
117:    *
118:    * @see #HealthCheckHandler(String, int)
119:    */
120:   public static final int DEFAULT_THROTTLE = 0;
121: 
122:   /**
123:    * The default path token name that indicates the individual health check to run.
124:    *
125:    * Value: {@value}
126:    *
127:    * @see #HealthCheckHandler(String, int)
128:    */
129:   public static final String DEFAULT_NAME_TOKEN = "name";
130:   private static final TypeToken<HealthCheck> HEALTH_CHECK_TYPE_TOKEN = TypeToken.of(HealthCheck.class);
131: 
132:   private final String name;
133:   private final int throttle;
134: 
135:   /**
136:    * Uses the default values of {@link #DEFAULT_NAME_TOKEN} and {@link #DEFAULT_THROTTLE}.
137:    *
138:    * @see #HealthCheckHandler(String, int)
139:    */
140:   public HealthCheckHandler() {
141:     this(DEFAULT_NAME_TOKEN, DEFAULT_THROTTLE);
142:   }
143: 
144:   /**
145:    * Uses the {@link #DEFAULT_THROTTLE} and the given name for the health check identifying path token.
146:    *
147:    * @param pathTokenName health check name
148:    * @see #HealthCheckHandler(String, int)
149:    */
150:   public HealthCheckHandler(String pathTokenName) {
151:     this(pathTokenName, DEFAULT_THROTTLE);
152:   }
153: 
154:   /**
155:    * Uses the {@link #DEFAULT_NAME_TOKEN} and the given concurrency level.
156:    *
157:    * @param throttle the concurrency level
158:    * @see #HealthCheckHandler(String, int)
159:    */
160:   public HealthCheckHandler(int throttle) {
161:     this(null, throttle);
162:   }
163: 
164:   /**
165:    * Constructor.
166:    * <p>
167:    * The path token name parameter specifies the name of the path token that, if present, indicates the single health check to execute.
168:    * If this path token is not present, all checks will be run.
169:    * <p>
170:    * The concurrency level indicates  the maximum allowed concurrency of health check execution.
171:    * <ul>
172:    * <li><code>&lt; 1</code> - infinite concurrency</li>
173:    * <li><code>= 1</code> - serialised (i.e. maximum concurrency of 1)</li>
174:    * <li><code>&gt; 1</code> - bounded concurrency</li>
175:    * </ul>
176:    * <p>
177:    * The actual parallelism of the health check executions is ultimately determined by the size of the application event loop.
178:    * General, the default value of {@code 0} (i.e. unbounded) is appropriate unless there are many health checks that are executed frequently as this may degrade the performance of other requests.
179:    *
180:    * @param pathTokenName the name of health check
181:    * @param concurrencyLevel the level of concurrency to use when executing health checks
182:    */
183:   protected HealthCheckHandler(String pathTokenName, int concurrencyLevel) {
184:     this.name = pathTokenName;
185:     this.throttle = concurrencyLevel;
186:   }
187: 
188:   /**
189:    * The level of concurrency to use when executing health checks.
190:    *
191:    * @return the level of concurrency to use when executing health checks
192:    * @see #HealthCheckHandler(String, int)
193:    */
194:   public int getConcurrencyLevel() {
195:     return throttle;
196:   }
197: 
198:   /**
199:    * The name of the path token that may indicate a particular health check to execute.
200:    *
201:    * @return the name of the path token that may indicate a particular health check to execute
202:    */
203:   public String getName() {
204:     return name;
205:   }
