51:   public DefaultExecController(int numThreads) {
52:     this.numThreads = numThreads;
53:     this.eventLoopGroup = new NioEventLoopGroup(numThreads, new ExecControllerBindingThreadFactory("ratpack-compute", Thread.MAX_PRIORITY));
54:     this.computeExecutor = MoreExecutors.listeningDecorator(eventLoopGroup);
55:     this.blockingExecutor = MoreExecutors.listeningDecorator(Executors.newCachedThreadPool(new ExecControllerBindingThreadFactory("ratpack-blocking", Thread.NORM_PRIORITY)));
56:     this.control = new FactoryBackedExecControl();
57:   }
58: 
59:   public static Optional<ExecController> getThreadBoundController() {
60:     return Optional.fromNullable(THREAD_BINDING.get());
61:   }
62: 
63:   public void close() {
64:     eventLoopGroup.shutdownGracefully(0, 0, TimeUnit.SECONDS);
65:     blockingExecutor.shutdown();
66:   }
67: 
68:   @Override
69:   public Execution getExecution() throws ExecutionException {
70:     Execution execution = executionHolder.get();
71:     if (execution == null) {
72:       throw new ExecutionException("No execution is bound to the current thread (are you calling this from a blocking operation or a manual created thread?)");
73:     } else {
74:       return execution;
75:     }
76:   }
