88:   @Override
89:   public void start(final Action<? super ratpack.exec.Execution> action) {
90:     if (!isManagedThread() || executionHolder.get() != null) {
91:       computeExecutor.submit(new Runnable() {
92:         @Override
93:         public void run() {
94:           start(action);
95:         }
96:       });
97:     } else {
98:       new Execution(action);
99:     }
100:   }
