201:       definition.registry(r -> {
202:         return Guice.registry(bindingsSpec -> {
203:           bindingsSpec.bindInstance(new FileBackedReloadInformant(scriptFile));
204:           ClosureUtil.configureDelegateFirst(bindingsSpec, closures.getBindings());
205:         }).apply(r);
206:       });
