235:   public class Execution extends SimpleMutableRegistry implements ratpack.exec.Execution {
236:     private final List<ExecInterceptor> interceptors = new LinkedList<>();
237:     private final Deque<Runnable> segments = new ConcurrentLinkedDeque<>();
238:     private final Queue<Runnable> onCompletes = new ConcurrentLinkedQueue<>();
239: 
240:     private Action<? super Throwable> errorHandler = new Action<Throwable>() {
241:       @Override
242:       public void execute(Throwable throwable) throws Exception {
243:         throw ExceptionUtils.toException(throwable);
244:       }
245:     };
246: 
247:     private final AtomicBoolean active = new AtomicBoolean();
248:     private boolean streaming;
249:     private boolean waiting;
250:     private boolean done;
251: 
252:     public Execution(Action<? super ratpack.exec.Execution> action) {
253:       segments.addLast(new UserCodeSegment(action));
254:       tryDrain();
255:     }
256: 
257:     @Override
258:     public <T> Promise<T> blocking(final Callable<T> operation) {
259:       return control.blocking(operation);
260:     }
261: 
262: 
263:     @Override
264:     public <T> Promise<T> promise(final Action<? super Fulfiller<T>> action) {
265:       return control.promise(action);
266:     }
267: 
268:     @Override
269:     public void fork(Action<? super ratpack.exec.Execution> action) {
270:       control.fork(action);
271:     }
272: 
273:     @Override
274:     public <T> void stream(Publisher<T> publisher, Subscriber<T> subscriber) {
275:       control.stream(publisher, subscriber);
276:     }
277: 
278:     @Override
279:     public void setErrorHandler(Action<? super Throwable> errorHandler) {
280:       this.errorHandler = errorHandler;
281:     }
282: 
283:     @Override
284:     public void addInterceptor(ExecInterceptor execInterceptor, Action<? super ratpack.exec.Execution> continuation) throws Exception {
285:       interceptors.add(execInterceptor);
286:       intercept(ExecInterceptor.ExecType.COMPUTE, Collections.singletonList(execInterceptor), continuation);
287:     }
288: 
289:     @Override
290:     public ExecController getController() {
291:       return DefaultExecController.this;
292:     }
293: 
294: 
295:     public void join(final Action<? super ratpack.exec.Execution> action) {
296:       segments.addFirst(new UserCodeSegment(action));
297:       waiting = false;
298:       tryDrain();
299:     }
300: 
301:     public void continueVia(final Runnable runnable) {
302:       segments.addLast(new Runnable() {
303:         @Override
304:         public void run() {
305:           waiting = true;
306:           runnable.run();
307:         }
308:       });
309:     }
310: 
311:     public void streamExecution(final Action<? super ratpack.exec.Execution> action) {
312:       segments.add(new UserCodeSegment(action));
313:       streaming = true;
314:       tryDrain();
315:     }
316: 
317:     public void completeStreamExecution(final Action<? super ratpack.exec.Execution> action) {
318:       segments.addLast(new UserCodeSegment(action));
319:       streaming = false;
320:       tryDrain();
321:     }
322: 
323:     private void tryDrain() {
324:       assertNotDone();
325:       if (!waiting && !segments.isEmpty()) {
326:         if (active.compareAndSet(false, true)) {
327:           drain();
328:         }
329:       }
330:     }
331: 
332:     private void runOnCompletes() {
333:       Runnable onComplete = onCompletes.poll();
334:       while (onComplete != null) {
335:         try {
336:           onComplete.run();
337:         } catch (Exception e) {
338:           LOGGER.warn("", e);
339:         } finally {
340:           onComplete = onCompletes.poll();
341:         }
342:       }
343:     }
344: 
345:     private void drain() {
346:       if (isManagedThread()) {
347:         executionHolder.set(this);
348:         try {
349:           Runnable segment = segments.poll();
350:           while (segment != null) {
351:             segment.run();
352:             if (waiting) { // the segment initiated an async op
353:               break;
354:             } else {
355:               segment = segments.poll();
356:               if (segment == null && !streaming) { // not waiting, not streaming and no more segments, we are done
357:                 done = true;
358:                 runOnCompletes();
359:               }
360:             }
361:           }
362:         } finally {
363:           executionHolder.remove();
364:           active.set(false);
365:         }
366:         if (waiting) {
367:           tryDrain();
368:         }
369:       } else {
370:         active.set(false);
371:         eventLoopGroup.submit(new Runnable() {
372:           @Override
373:           public void run() {
374:             tryDrain();
375:           }
376:         });
377:       }
378:     }
379: 
380:     @Override
381:     public void onComplete(Runnable runnable) {
382:       assertNotDone();
383:       onCompletes.add(runnable);
384:     }
385: 
386:     private void assertNotDone() {
387:       if (done) {
388:         throw new ExecutionException("execution is complete");
389:       }
390:     }
391: 
392:     public void intercept(final ExecInterceptor.ExecType execType, final List<ExecInterceptor> interceptors, final Action<? super Execution> action) throws Exception {
393:       new InterceptedOperation(execType, interceptors) {
394:         @Override
395:         protected void performOperation() throws Exception {
396:           action.execute(Execution.this);
397:         }
398:       }.run();
399:     }
400: 
401:     /**
402:      * An execution segment that executes “user code” (i.e. not execution management infrastructure)
403:      */
404:     private class UserCodeSegment implements Runnable {
405:       private final Action<? super ratpack.exec.Execution> action;
406: 
407:       public UserCodeSegment(Action<? super ratpack.exec.Execution> action) {
408:         this.action = action;
409:       }
410: 
411:       @Override
412:       public void run() {
413:         try {
414:           try {
415:             intercept(ExecInterceptor.ExecType.COMPUTE, interceptors, action);
416:           } catch (ExecutionSegmentTerminationError e) {
417:             throw e.getCause();
418:           }
419:         } catch (final Throwable e) {
420:           segments.clear();
421:           segments.addFirst(new Runnable() {
422:             @Override
423:             public void run() {
424:               try {
425:                 errorHandler.execute(e);
426:               } catch (final Throwable e) {
427:                 segments.addFirst(new UserCodeSegment(new Action<ratpack.exec.Execution>() {
428:                   @Override
429:                   public void execute(ratpack.exec.Execution execution) throws Exception {
430:                     throw e;
431:                   }
432:                 }));
433:               }
434:             }
435:           });
436:         }
437:       }
438:     }
439:   }
440: 
441:   @Override
442:   public ExecControl getControl() {
443:     return control;
444:   }
445: 
446:   private class ExecControllerBindingThreadFactory extends DefaultThreadFactory {
447:     public ExecControllerBindingThreadFactory(String name, int priority) {
448:       super(name, priority);
449:     }
450: 
451:     @Override
452:     public Thread newThread(final Runnable r) {
453:       return super.newThread(new Runnable() {
454:         @Override
455:         public void run() {
456:           THREAD_BINDING.set(DefaultExecController.this);
457:           r.run();
458:         }
459:       });
460:     }
461: 
462:   }
463: 
464:   @Override
465:   public boolean isManagedThread() {
466:     Optional<ExecController> threadBoundController = getThreadBoundController();
467:     return threadBoundController.isPresent() && threadBoundController.get() == this;
468:   }
469: 
470:   @Override
471:   public int getNumThreads() {
472:     return numThreads;
473:   }
474: 
475: }
