74:               public void success(final T value) {
75:                 if (!fulfilled.compareAndSet(false, true)) {
76:                   LOGGER.error("", new OverlappingExecutionException("promise already fulfilled"));
77:                   return;
78:                 }
79: 
80:                 execution.join(new Action<ratpack.exec.Execution>() {
81:                   @Override
82:                   public void execute(ratpack.exec.Execution execution) throws Exception {
83:                     then.execute(value);
84:                   }
85:                 });
86:               }
87:             });
88:           } catch (final Exception e) {
89:             if (!fulfilled.compareAndSet(false, true)) {
90:               LOGGER.error("", new OverlappingExecutionException("exception thrown after promise was fulfilled", e));
91:             } else {
92:               execution.join(new Action<ratpack.exec.Execution>() {
93:                 @Override
94:                 public void execute(ratpack.exec.Execution execution) throws Exception {
95:                   throw ExceptionUtils.toException(e);
96:                 }
97:               });
98:             }
99:           }
100:         }
