35: /**
36:  * An extension module that provides a cookie based store for sessions.
37:  * <h3>Provides</h3>
38:  * <ul>
39:  * <li>{@link ratpack.session.store.SessionStorage} - deserialized from the client's cookie</li>
40:  * </ul>
41:  * <h3>Getting the session storage</h3>
42:  *
43:  * <pre class="tested java">{@code
44:  * import ratpack.handling.*;
45:  * import ratpack.session.store.SessionStorage;
46:  *
47:  * class MyHandler implements Handler {
48:  *   void handle(Context ctx) {
49:  *     SessionStorage sessionStorage = ctx.getRequest().get(SessionStorage.class);
50:  *     sessionStorage.get("value", String.class).then( (value) -> { render(value.orElse("not set"));});
51:  *
52:  *   }
53:  * }
54:  * }</pre>
55:  * <h3>Configuration</h3>
56:  * <p>
57:  * This module also provides a programmatic configurable object that helps customize various elements.
58:  * <table>
59:  *   <caption>Configurable Elements</caption>
60:  *   <tr>
61:  *     <th>sessionName</th>
62:  *     <td>The name of the cookie in which the session is stored. Defaults to <strong>ratpack_session</strong>.</td>
63:  *   </tr>
64:  *   <tr>
65:  *     <th>secretToken</th>
66:  *     <td>The token used to sign the serialized session to prevent tampering. If not set, this is set to a time based value.
67:  *          If working with clustered sessions, not being tied to any ratpack app instance,
68:  *          {@code secretToken} has to be the same in every ratpack instance configuration.
69:  *     </td>
70:  *   </tr>
71:  *   <tr>
72:  *     <th>macAlgorithm</th>
73:  *     <td>The {@link javax.crypto.Mac} algorithm used to sign the serialized session with the <strong>secretToken</strong>.</td>
74:  *   </tr>
75:  *   <tr>
76:  *     <th>secretKey</th>
77:  *     <td>The secret key used in the symmetric-key encyrption/decryption with the serialized session.</td>
78:  *   </tr>
79:  *   <tr>
80:  *     <th>cipherAlgorithm</th>
81:  *     <td>The {@link javax.crypto.Cipher} algorithm used to encrypt/decrypt the serialized session, e.g. <strong>AES/CBC/PKCS5Padding</strong> which is also the default value.</td>
82:  *   </tr>
83:  *   <tr>
84:  *     <th>path</th>
85:  *     <td>Define the scope of the cookie. It tells the browser to use the cookie onl when requesting endpoints contained (prefixed)
86:  *          by the {@code path}. If {@code path == '/'} the session cookies will be send for every endpoint.
87:  *     </td>
88:  *   </tr>
89:  *   <tr>
90:  *     <th>domain</th>
91:  *     <td>Define the scope of the cookie. It tells the browser what domain the cookie belongs to.
92:  *     </td>
93:  *   </tr>
94:  *   <tr>
95:  *     <th>maxCookieSize</th>
96:  *     <td>Define the maximum size of the cookie session partial.
97:  *          If serialized and encoded session is longer than {@code maxCookieSize} the session will be partitioned.
98:  *          Every partition will be separate cookie prefixed with {@code sessionName} plus index value.
99:  *     </td>
100:  *   </tr>
101:  *   <tr>
102:  *     <th>maxInactivityInterval</th>
103:  *     <td>Define the maximum session inactivity interval. When timed out, all entries from the session will be gone.
104:  *     </td>
105:  *   </tr>
106:  *   <tr>
107:  *     <th>sessionService</th>
108:  *     <td>The {@link ratpack.session.clientside.SessionService} service used to serialize/deserialize the session entries.
109:  *          Defaults to {@link ratpack.session.clientside.internal.DefaultClientSessionService}.
110:  *     </td>
111:  *   </tr>
112:  *   <tr>
113:  *     <th>valueSerializer</th>
114:  *     <td>The {@link ratpack.session.clientside.ValueSerializer} used to serialize/deserialize particular session entry value.
115:  *          Defaults to {@link ratpack.session.clientside.serializer.JavaValueSerializer}.
116:  *          Available is {@link ratpack.session.clientside.serializer.StringValueSerializer} too.
117:  *     </td>
118:  *   </tr>
119:  * </table>
120:  *
121:  * <h3>Configuration Example</h3>
122:  * <pre class="java">{@code
123:  * import ratpack.guice.Guice;
124:  * import ratpack.http.client.ReceivedResponse;
125:  * import ratpack.session.clientside.ClientSideSessionsModule;
126:  * import ratpack.session.store.SessionStorage;
127:  * import ratpack.test.embed.EmbeddedApp;
128:  * import ratpack.session.clientside.serializer.StringValueSerializer;
129:  *
130:  * import static org.junit.Assert.*;
131:  *
132:  * public class ClientSideSessionsModuleConfigExample {
133:  *   public static void main(String[] args) throws Exception {
134:  *     EmbeddedApp.of(s -> s
135:  *       .registry(Guice.registry(b ->
136:  *         b.module(ClientSideSessionsModule.class, config -> {
137:  *           config.setSessionName("session-name");
138:  *           config.setSecretToken("your token for signing");
139:  *           // config.setSecretKey("key for cipher");
140:  *           // config.setMacAlgorithm("MAC algorithm for signing");
141:  *           // config.setCipherAlgorithm("Cipher Algorithm");
142:  *           // config.setPath("/");
143:  *           // config.setDomain("www.example.com");
144:  *           // config.setMaxCookieSize(1024);
145:  *           // config.setMaxInactivityInterval(Duration.ofSeconds(60));
146:  *           config.setValueSerializer(new StringValueSerializer());
147:  *         })
148:  *       ))
149:  *       .handlers(chain -> chain
150:  *         .get(ctx -> {
151:  *           SessionStorage sessionStorage = ctx.getRequest().get(SessionStorage.class);
152:  *           sessionStorage.get("value",String.class).then( value -> { ctx.render(value.orElse("not set"));});
153:  *         })
154:  *         .get("set/:value", ctx -> {
155:  *           SessionStorage sessionStorage = ctx.getRequest().get(SessionStorage.class);
156:  *           String value = ctx.getPathTokens().get("value");
157:  *           sessionStorage.set("value", value).then( success->{
158:  *            ctx.render(value);
159:  *           });
160:  *
161:  *         })
162:  *       )
163:  *     ).test(client -> {
164:  *       ReceivedResponse response = client.get();
165:  *       assertEquals("not set", response.getBody().getText());
166:  *       assertFalse("No cookies should be set", response.getHeaders().contains("Set-Cookie"));
167:  *
168:  *       response = client.get("set/foo");
169:  *       assertEquals("foo", response.getBody().getText());
170:  *       assertTrue("We set a value", response.getHeaders().contains("Set-Cookie"));
171:  *       assertTrue("Session uses our session name", response.getHeaders().get("Set-Cookie").contains("session-name"));
172:  *
173:  *       response = client.get();
174:  *       assertEquals("foo", response.getBody().getText());
175:  *       assertFalse("We did not update session", response.getHeaders().contains("Set-Cookie"));
176:  *     });
177:  *   }
178:  * }
179:  * }</pre>
180:  *
181:  * <h3>Notes</h3>
182:  * <p>
183:  * Because the session is serialized to the client, all key value pairs in the session
184:  * are String based. The max cookie size for a client is 4k so it's important to keep
185:  * this in mind when using the ClientSideSessionsModule.
186:  *
187:  * <p>
188:  * By default your session will be signed but not encrypted. This is because the <strong>secretKey</strong>
189:  * is not set by default. That is, your users will not be able to tamper with the
190:  * cookie but they can still read the key value pairs that you have set. If you want to render
191:  * the entire cookie unreadable make sure you set a <strong>secretKey</strong>
192:  *
193:  * <p>
194:  * When setting your own <strong>secretKey</strong> and <strong>cipherAlgorithm</strong>
195:  * make sure that the key length is acceptable according to the algorithm you have chosen.
196:  *
197:  */
198: public class ClientSideSessionsModule extends ConfigurableModule<ClientSideSessionsModule.Config> {
199: 
200:   @Override
201:   protected void configure() {
202:     Multibinder.newSetBinder(binder(), HandlerDecorator.class).addBinding().toProvider(CookieBasedSessionStorageHandlerDecorator.class);
203:   }
204: 
205:   @SuppressWarnings("UnusedDeclaration")
206:   @Provides
207:   @Singleton
208:   Signer provideSigner(Config config) {
209:     byte[] token = config.getSecretToken().getBytes(CharsetUtil.UTF_8);
210:     return new DefaultSigner(new SecretKeySpec(token, config.getMacAlgorithm()));
211:   }
212: 
213:   @SuppressWarnings("UnusedDeclaration")
214:   @Provides
215:   @Singleton
216:   Crypto provideCrypto(Config config) {
217:     if (config.getSecretKey() == null || config.getCipherAlgorithm() == null) {
218:       return NoCrypto.INSTANCE;
219:     } else {
220:       return new DefaultCrypto(config.getSecretKey().getBytes(CharsetUtil.UTF_8), config.getCipherAlgorithm());
221:     }
222:   }
223: 
224:   @SuppressWarnings("UnusedDeclaration")
225:   @Provides
226:   @Singleton
227:   SessionService provideSessionService(ByteBufAllocator byteBufAllocator, Config config, Signer signer, Crypto crypto, ValueSerializer valueSerializer) {
228:     SessionService sessionService = config.getSessionService();
229:     if (sessionService == null) {
230:       sessionService = new DefaultClientSessionService(byteBufAllocator, signer, crypto, valueSerializer);
231:     }
232:     return sessionService;
233:   }
234: 
235:   @SuppressWarnings("UnusedDeclaration")
236:   @Provides
237:   @Singleton
238:   ValueSerializer provideValueSerializer(Config config) {
239:     ValueSerializer valueSerializer = config.getValueSerializer();
240:     if (valueSerializer == null) {
241:       valueSerializer = new JavaValueSerializer();
242:     }
243:     return valueSerializer;
244:   }
