115:    * @param userRegistry the user defined registry contents that will override any default registry entries
116:    * @return a fully defined registry that can be used to launch an application
117:    *
118:    * @throws Exception if there is an error creating the registry.
119:    */
120:   public static Registry baseRegistry(ServerConfig serverConfig, Registry userRegistry) throws Exception {
121:     ErrorHandler errorHandler = serverConfig.isDevelopment() ? new DefaultDevelopmentErrorHandler() : new DefaultProductionErrorHandler();
122:     ExecController execController = new DefaultExecController(serverConfig.getThreads());
123:     PooledByteBufAllocator byteBufAllocator = PooledByteBufAllocator.DEFAULT;
124: 
125:     RegistryBuilder baseRegistry = Registries.registry()
126:       .add(ServerConfig.class, serverConfig)
127:       .add(ByteBufAllocator.class, byteBufAllocator)
128:       .add(ExecController.class, execController)
129:       .add(MimeTypes.class, new ActivationBackedMimeTypes())
130:       .add(PublicAddress.class, new DefaultPublicAddress(serverConfig.getPublicAddress(), serverConfig.getSSLContext() == null ? HTTP_SCHEME : HTTPS_SCHEME))
131:       .add(Redirector.class, new DefaultRedirector())
132:       .add(ClientErrorHandler.class, errorHandler)
133:       .add(ServerErrorHandler.class, errorHandler)
134:       .with(new DefaultFileRenderer().register())
135:       .with(new PromiseRenderer().register())
136:       .with(new PublisherRenderer().register())
137:       .with(new RenderableRenderer().register())
138:       .with(new CharSequenceRenderer().register())
139:       .add(FormParser.class, FormParser.multiPart())
140:       .add(FormParser.class, FormParser.urlEncoded())
141:       .add(HttpClient.class, HttpClients.httpClient(execController, byteBufAllocator, serverConfig.getMaxContentLength()));
142: 
143:     if (serverConfig.isHasBaseDir()) {
144:       baseRegistry.add(FileSystemBinding.class, serverConfig.getBaseDir());
145:     }
